#!/usr/bin/env python3
import json
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

DB_PATH = "/var/lib/job-queue/jobs.sqlite3"


def open_db():
    db = sqlite3.connect(DB_PATH, timeout=30.0)
    db.execute("PRAGMA busy_timeout=30000")
    db.execute("PRAGMA journal_mode=WAL")
    db.execute("PRAGMA synchronous=FULL")
    return db


def route(path):
    parts = urlsplit(path).path.split("/")
    if len(parts) == 3 and parts[1] == "jobs" and parts[2]:
        return unquote(parts[2])
    return None


class QueueHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def send_bytes(self, status, body=b"", content_type=None):
        self.send_response(status)
        if content_type is not None:
            self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Connection", "close")
        self.end_headers()
        if body:
            self.wfile.write(body)
        self.close_connection = True

    def do_GET(self):
        if urlsplit(self.path).path == "/health":
            self.send_bytes(200, b"ready")
            return

        job_id = route(self.path)
        if job_id is None:
            self.send_bytes(404)
            return

        try:
            with open_db() as db:
                row = db.execute(
                    "SELECT id, payload, status, result, attempts "
                    "FROM jobs WHERE id = ?", (job_id,)
                ).fetchone()
        except sqlite3.Error:
            self.send_bytes(500)
            return

        if row is None:
            self.send_bytes(404)
            return
        body = json.dumps(
            {
                "id": row[0],
                "payload": row[1],
                "status": row[2],
                "result": row[3],
                "attempts": row[4],
            },
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
        self.send_bytes(200, body, "application/json; charset=utf-8")

    def do_POST(self):
        job_id = route(self.path)
        if job_id is None:
            self.send_bytes(404)
            return

        value = self.headers.get("Content-Length")
        try:
            length = int(value) if value is not None else 0
        except ValueError:
            self.send_bytes(400)
            return
        if length < 0:
            self.send_bytes(400)
            return
        try:
            payload = self.rfile.read(length).decode("utf-8")
        except UnicodeDecodeError:
            self.send_bytes(400)
            return

        try:
            with open_db() as db:
                db.execute(
                    "INSERT OR IGNORE INTO jobs "
                    "(id, payload, status, result, attempts) "
                    "VALUES (?, ?, 'queued', NULL, 0)",
                    (job_id, payload),
                )
                db.commit()
        except sqlite3.Error:
            self.send_bytes(500)
            return
        self.send_bytes(202)

    def log_message(self, format, *args):
        return


class QueueServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


if __name__ == "__main__":
    QueueServer(("0.0.0.0", 8080), QueueHandler).serve_forever()

